class VendingMachine:
    MINIMUM_BALANCE = 0

    def __init__(self):
        self._inventory = {}
        self._balance = 0

    @property
    def inventory(self):
        return self._inventory

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, value):
        self._balance = value

    def add_item(self, item_name, price, quantity):
        if not self.restock_item(item_name, quantity):
            self._inventory[item_name] = {'price': price, 'quantity': quantity}

    def insert_coin(self, amount):
        self.balance += amount
        return self.balance

    def purchase_item(self, item_name):
        if not self._is_valid_purchase(item_name):
            return False
        self._process_purchase(item_name)
        return self.balance

    def restock_item(self, item_name, quantity):
        if item_name in self._inventory:
            self._inventory[item_name]['quantity'] += quantity
            return True
        return False

    def display_items(self):
        if not self._inventory:
            return False
        return self._format_items_for_display()

    def _is_valid_purchase(self, item_name):
        if item_name not in self._inventory:
            return False
        item = self._inventory[item_name]
        return item['quantity'] > 0 and self.balance >= item['price']

    def _process_purchase(self, item_name):
        item = self._inventory[item_name]
        self.balance -= item['price']
        item['quantity'] -= 1

    def _format_items_for_display(self):
        return "\n".join(self._format_item_line(name, info) for name, info in self._inventory.items())

    def _format_item_line(self, item_name, item_info):
        return f"{item_name} - ${item_info['price']} [{item_info['quantity']}]"
